// Extract email metadata
const emailData = $input.first().json;

const subject = emailData.subject || '';
const from = emailData.from || '';
const receivedDate = emailData.date || new Date().toISOString();
const messageId = emailData.messageId || '';

// Check if email has PDF attachments
const attachments = emailData.attachments || [];
const pdfAttachments = attachments.filter(att => 
  att.mimeType === 'application/pdf' || 
  att.filename.toLowerCase().endsWith('.pdf')
);

if (pdfAttachments.length === 0) {
  throw new Error('No PDF attachments found in email');
}

// Prepare for PDF extraction
return {
  json: {
    emailSubject: subject,
    labCompany: from,
    receivedDate: receivedDate,
    messageId: messageId,
    pdfCount: pdfAttachments.length,
    // Pass through for next node
    hasAttachments: true
  }
};

// Parse lab result PDF text to extract patient info and test values
const pdfText = $input.first().json.text || '';

// Helper function to extract value after a label
function extractValue(text, label) {
  const regex = new RegExp(label + '\\s*:?\\s*([^\\n]+)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : null;
}

// Helper function to extract date
function extractDate(text, label) {
  const regex = new RegExp(label + '\\s*:?\\s*(\\d{1,2}[/-]\\d{1,2}[/-]\\d{2,4})', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : null;
}

// Extract patient demographics
const patientName = extractValue(pdfText, 'Patient Name|Patient');
const patientDOB = extractDate(pdfText, 'Date of Birth|DOB|Birth Date');
const patientMRN = extractValue(pdfText, 'MRN|Medical Record|Patient ID');
const patientGender = extractValue(pdfText, 'Gender|Sex');

// Extract test information
const collectionDate = extractDate(pdfText, 'Collection Date|Collected|Specimen Date');
const reportDate = extractDate(pdfText, 'Report Date|Reported');
const orderingProvider = extractValue(pdfText, 'Ordering Provider|Physician|Doctor');

// Extract test results (simplified - real implementation needs more robust parsing)
// Format: Test Name | Value | Reference Range | Flag
const testResults = [];

// Common lab test patterns to look for
const commonTests = [
  { name: 'Glucose', pattern: /Glucose[\\s:]*([\\d.]+)\\s*mg\\/dL/i },
  { name: 'Hemoglobin', pattern: /Hemoglobin[\\s:]*([\\d.]+)\\s*g\\/dL/i },
  { name: 'WBC', pattern: /WBC|White Blood Cell[\\s:]*([\\d.]+)\\s*K\\/uL/i },
  { name: 'RBC', pattern: /RBC|Red Blood Cell[\\s:]*([\\d.]+)\\s*M\\/uL/i },
  { name: 'Platelet', pattern: /Platelet[\\s:]*([\\d.]+)\\s*K\\/uL/i },
  { name: 'Total Cholesterol', pattern: /Total Cholesterol[\\s:]*([\\d.]+)\\s*mg\\/dL/i },
  { name: 'LDL', pattern: /LDL[\\s:]*([\\d.]+)\\s*mg\\/dL/i },
  { name: 'HDL', pattern: /HDL[\\s:]*([\\d.]+)\\s*mg\\/dL/i },
  { name: 'Triglycerides', pattern: /Triglycerides[\\s:]*([\\d.]+)\\s*mg\\/dL/i },
  { name: 'Creatinine', pattern: /Creatinine[\\s:]*([\\d.]+)\\s*mg\\/dL/i },
  { name: 'eGFR', pattern: /eGFR[\\s:]*([\\d.]+)/i },
  { name: 'TSH', pattern: /TSH[\\s:]*([\\d.]+)\\s*uIU\\/mL/i },
  { name: 'A1C', pattern: /A1C|Hemoglobin A1c[\\s:]*([\\d.]+)\\s*%/i }
];

commonTests.forEach(test => {
  const match = pdfText.match(test.pattern);
  if (match) {
    testResults.push({
      testName: test.name,
      value: parseFloat(match[1]),
      // Reference ranges would be extracted from PDF or looked up in database
      flagged: false // Will be determined by AI triage
    });
  }
});

// Check if we successfully extracted patient info
if (!patientName && !patientMRN) {
  throw new Error('Failed to extract patient information from PDF. Manual review needed.');
}

// Check if we extracted any test results
if (testResults.length === 0) {
  console.warn('No test results extracted from PDF. May need manual parsing.');
}

// Prepare output for AI triage
return {
  json: {
    // Patient demographics
    patient: {
      name: patientName || 'Unknown',
      dateOfBirth: patientDOB || null,
      mrn: patientMRN || null,
      gender: patientGender || null
    },

    // Test metadata
    labOrder: {
      collectionDate: collectionDate || null,
      reportDate: reportDate || new Date().toISOString().split('T')[0],
      orderingProvider: orderingProvider || 'Dr. Jennifer',
      labCompany: $('Extract Email Metadata').first().json.labCompany || 'Unknown'
    },

    // Test results
    tests: testResults,
    testCount: testResults.length,

    // For logging
    pdfTextLength: pdfText.length,
    extractionTimestamp: new Date().toISOString(),

    // Pass through email metadata
    emailMetadata: $('Extract Email Metadata').first().json
  }
};

// Merge patient demographics from database with lab results
const labData = $('Parse Lab Results from PDF').first().json;
const patientData = $input.first().json;

// Prepare complete context for AI triage
const fullContext = {
  patient: {
    // From database (more reliable)
    id: patientData.Patient_ID || null,
    name: patientData.Patient_Name || labData.patient.name,
    dateOfBirth: patientData.DOB || labData.patient.dateOfBirth,
    phone: patientData.Phone || null,
    email: patientData.Email || null,
    primaryDoctor: patientData.Primary_Doctor || labData.labOrder.orderingProvider,
    lastVisitDate: patientData.Last_Visit_Date || null,

    // From lab PDF
    mrn: labData.patient.mrn,
    gender: labData.patient.gender
  },

  labOrder: labData.labOrder,

  tests: labData.tests,
  testCount: labData.testCount,

  // For audit trail
  metadata: {
    receivedVia: 'email',
    emailSubject: labData.emailMetadata.emailSubject,
    extractionTimestamp: labData.extractionTimestamp
  }
};

return {
  json: fullContext
};

